import{_ as a}from"./chunks/library-overview.Bu864uIA.js";import{_ as e}from"./chunks/volume-settings.DLnHK18N.js";import{_ as d,o as s,c as o,a2 as n}from"./chunks/framework.Dx-TCpNt.js";const k=JSON.parse('{"title":"ライブラリとインポート","description":"ライブラリは、アプリを読み込むたびに raw/ をスキャンして組み立てられます。データベースも、スキャンをコピーするインポート手順もありません。ディレクトリ構造が設定そのもの です。","frontmatter":{"description":"ライブラリは、アプリを読み込むたびに raw/ をスキャンして組み立てられます。データベースも、スキャンをコピーするインポート手順もありません。ディレクトリ構造が設定そのもの です。"},"headers":[],"relativePath":"ja/guide/gallery.md","filePath":"ja/guide/gallery.md","lastUpdated":1794776663000}'),r={name:"ja/guide/gallery.md"};function i(l,t,c,p,h,g){return s(),o("div",null,[...t[0]||(t[0]=[n(`<h1 id="ライブラリとインポート" tabindex="-1">ライブラリとインポート <a class="header-anchor" href="#ライブラリとインポート" aria-label="Permalink to &quot;ライブラリとインポート&quot;">​</a></h1><p>ライブラリは、アプリを読み込むたびに <code>raw/</code> をスキャンして組み立てられます。データベースも、スキャンをコピーするインポート手順もありません。<strong>ディレクトリ構造が設定そのもの</strong> です。</p><p>このページでは、ファイルの置き方、スキャナーが言語を対応付ける仕組み、別の場所にあるフォルダのリンク方法、そしてインポートの入口がどこへ続くのかを説明します。</p><h2 id="解決する課題" tabindex="-1">解決する課題 <a class="header-anchor" href="#解決する課題" aria-label="Permalink to &quot;解決する課題&quot;">​</a></h2><p>漫画のスキャンは、<code>Vol.14/Japanese/ch01</code>、<code>点兔第14卷/ja/172</code>、<code>manga/zh-cn/172</code> のように、前の持ち主の気分でさまざまな形で届きます。名前も場所も変えずに、巻と話を一覧できる棚が1つほしい。各言語の1ページ目をきちんと対応付け、ファイルが欠けている場所を教えてほしい。それがこのライブラリです。</p><h2 id="ディレクトリ構成" tabindex="-1">ディレクトリ構成 <a class="header-anchor" href="#ディレクトリ構成" aria-label="Permalink to &quot;ディレクトリ構成&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>raw/</span></span>
<span class="line"><span>  &lt;volume&gt;/</span></span>
<span class="line"><span>    &lt;language-dir&gt;/</span></span>
<span class="line"><span>      &lt;chapter&gt;/</span></span>
<span class="line"><span>        001.jpg</span></span>
<span class="line"><span>        002.jpg</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><ul><li><strong>巻</strong> は <code>raw/</code> 直下の任意のフォルダです。</li><li><strong>話</strong> は言語ディレクトリ内の任意のフォルダです。話は言語をまたいで統合されるため、ある翻訳版では話フォルダがまるごと欠けていることもあります。</li><li><strong>ページはファイル名ではなく、並べ替えた位置で対応付けられます。</strong> 各言語のファイルを自然順（連続する数字を数値として比較）で並べ、そのインデックスで対応付けます。<code>1.jpg</code>、<code>2.jpg</code>、<code>10.jpg</code> も正しい順に並びます。</li></ul><figure class="shot"><img src="`+a+`" alt="巻、話、言語バッジを表示したライブラリサイドバー"><figcaption>サイドバーは 巻 → 話 → ページ の順に表示します。言語バッジは巻に存在する版を示し、警告はその場に出ます。</figcaption></figure><h2 id="言語ディレクトリ名" tabindex="-1">言語ディレクトリ名 <a class="header-anchor" href="#言語ディレクトリ名" aria-label="Permalink to &quot;言語ディレクトリ名&quot;">​</a></h2><p>スキャナーはフォルダ名を正規化し（小文字化、空白とアンダースコアをハイフンに変換）、別名と照合します。</p><table tabindex="0"><thead><tr><th>言語</th><th>受け付けるディレクトリ名</th></tr></thead><tbody><tr><td>日本語（<code>ja</code>）</td><td><code>ja</code>, <code>jp</code>, <code>jpn</code>, <code>japanese</code>, <code>ja-jp</code>, <code>日</code>, <code>日本語</code>, <code>日文</code></td></tr><tr><td>中国語（<code>zh</code>）</td><td><code>zh</code>, <code>zh-cn</code>, <code>zh-hans</code>, <code>zh-sg</code>, <code>cn</code>, <code>chs</code>, <code>zh-tw</code>, <code>zh-hk</code>, <code>zh-hant</code>, <code>cht</code>, <code>tw</code>, <code>hk</code>, <code>中</code>, <code>中文</code>, <code>繁中</code>, <code>简中</code></td></tr><tr><td>英語（<code>en</code>）</td><td><code>en</code>, <code>en-us</code>, <code>en-gb</code>, <code>us</code>, <code>uk</code>, <code>eng</code>, <code>english</code>, <code>英</code>, <code>英文</code></td></tr></tbody></table><p>フォルダ名を認識できない場合、巻は表示されますが警告が付きます。<strong>巻の設定</strong>（巻の行の歯車）を開き、ディレクトリを言語に割り当ててください。この選択は <code>data/library.json</code> に保存されます。</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;volumes&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;ご注文はうさぎですか? 第14巻&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;dirs&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;ja&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;raw-ja&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;zh&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;raw-zh&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>巻に持たせられる言語の数は、割り当てた分だけです。組み込みの3言語は、いわば常連の顔ぶれ。比較リーダーは、現在のページに実際に存在する言語だけを提示します。</p><h2 id="巻の設定" tabindex="-1">巻の設定 <a class="header-anchor" href="#巻の設定" aria-label="Permalink to &quot;巻の設定&quot;">​</a></h2><p>巻の設定は、フォルダがきちんと名乗ってくれなかった巻のための修理場です。巻の行の歯車から開きます。</p><ol><li>ダイアログには、その巻で検出された言語ごとのドロップダウンに加えて、<strong>日本語</strong>、<strong>中文</strong>、<strong>英語</strong>が既定で並びます。</li><li>それぞれの言語が入っているサブフォルダを選びます。<strong>未使用 / 自動</strong>のままなら自動認識に任せます。</li><li><strong>保存</strong>を押すとライブラリが再走査され、巻の言語バッジが更新されます。</li><li><strong>ライブラリから削除</strong>は <code>raw/</code> のリンクだけを消します。元のフォルダの画像と <code>data/pages/</code> の注釈は残ります。</li></ol><p>1つのフォルダを割り当てられる言語は1つだけです。すでに使われたフォルダは他のドロップダウンから消えます。言語フォルダが1つも見つからない場合は、その旨と、巻に出ている警告の理由がダイアログに表示されます。</p><figure class="shot"><img src="`+e+'" alt="巻の設定ダイアログ。ja、zh、en のドロップダウンと「ライブラリから削除」「キャンセル」「保存」"><figcaption>巻の設定。各言語のドロップダウンがサブフォルダーを指します。保存すると再スキャンされ、「ライブラリから削除」は raw/ のリンクだけを消します。</figcaption></figure><div class="tip custom-block"><p class="custom-block-title">注釈の前に割り当てを決める</p><p>コマとノートは巻・話ごとに保存されます。あとから割り当てを変えると、ページデータを見つけられなくなることがあります。割り当てを決め、数ページ開いて確認してから、コマの修正を始めてください。</p></div><h2 id="別の場所にあるフォルダの追加" tabindex="-1">別の場所にあるフォルダの追加 <a class="header-anchor" href="#別の場所にあるフォルダの追加" aria-label="Permalink to &quot;別の場所にあるフォルダの追加&quot;">​</a></h2><p><strong>＋ マンガを追加</strong> には2つのモードがあります。</p><table tabindex="0"><thead><tr><th>モード</th><th>動作</th></tr></thead><tbody><tr><td>パスを空欄にする</td><td><code>raw/</code> の下に空のフォルダを作成します。</td></tr><tr><td>既存のフォルダを選ぶ</td><td>元のフォルダを指す <strong>フォルダリンク</strong> を <code>raw/</code> の下に作成します。画像はコピーされず、リンクは通常のフォルダと同じように動くので、注釈もそのまま読み書きできます。</td></tr></tbody></table><p>任意: 巻に別の表示名を付けられます。フィールド下のヒントには、想定される構成 <code>language/chapter/page.jpg</code> が表示されます。</p><p><strong>ライブラリから削除</strong>（巻の設定内）は <code>raw/</code> の下のリンクだけを削除します。元のフォルダの画像はそのまま残り、<code>data/pages/</code> に保存済みの注釈も保持されます。</p><p>通常のブラウザではフォルダ選択ダイアログを開けません。絶対パスを直接入力するか、デスクトップ版で <strong>フォルダを選択…</strong> をクリックしてください。</p><h2 id="ページと言語の役割" tabindex="-1">ページと言語の役割 <a class="header-anchor" href="#ページと言語の役割" aria-label="Permalink to &quot;ページと言語の役割&quot;">​</a></h2><p>混同しやすい3つの「役割」があります。</p><table tabindex="0"><thead><tr><th>役割</th><th>指定する場所</th><th>影響する範囲</th></tr></thead><tbody><tr><td><strong>下地画像</strong>（基準画像）</td><td>コマ分割ワークベンチのツールバー</td><td>どの言語の画像にコマを描くか。コマの矩形はそのページの全言語で共有されます。</td></tr><tr><td><strong>比較言語</strong></td><td>比較リーダーの言語チップ</td><td>表示する言語とその順序。すべての言語を有効にする必要はありません。</td></tr><tr><td><strong>優先言語</strong></td><td>PNG エクスポート</td><td>ページ全体と現在のコマの PNG は下地画像の言語を使い、3言語コラージュは選択した比較言語を使います。</td></tr></tbody></table><p>コマとノートは言語ごとではなく、ページごとに1回だけ保存されます。位置合わせのオフセットは言語ごと、任意でコマごとに保存されます。</p><h2 id="表示される警告" tabindex="-1">表示される警告 <a class="header-anchor" href="#表示される警告" aria-label="Permalink to &quot;表示される警告&quot;">​</a></h2><p>ライブラリの警告はちょっとした噂話で、エラーではありません。ページはちゃんと開きます。</p><table tabindex="0"><thead><tr><th>警告</th><th>意味</th><th>対処</th></tr></thead><tbody><tr><td><em>言語ディレクトリが認識されません</em></td><td>サブフォルダがどの別名にも一致しませんでした。</td><td>巻の設定で割り当てるか、名前を変更します。</td></tr><tr><td><em>未認識のディレクトリ：…</em></td><td>言語フォルダの隣に余分なフォルダがあります。</td><td>割り当てるか、無視します。</td></tr><tr><td><em>言語間でページ数が異なります</em></td><td>言語ごとにファイル数が違います。</td><td>対応付けはインデックス順です。欠けているページを追加するか削除します。</td></tr><tr><td><em>この話に混在した拡張子があります</em></td><td>例：<code>.jpg</code> と <code>.png</code> が交互にあります。</td><td>通常は無害です。サムネイルを揃えたいなら形式を統一してください。</td></tr><tr><td><em>ファイル名がページ番号と一致しません</em></td><td>ファイル名先頭の数字が並び順と異なります。</td><td>欠落や余分なページを示す不一致なら、名前を変更します。</td></tr></tbody></table><h2 id="特殊なディレクトリ構成" tabindex="-1">特殊なディレクトリ構成 <a class="header-anchor" href="#特殊なディレクトリ構成" aria-label="Permalink to &quot;特殊なディレクトリ構成&quot;">​</a></h2><p>既定の構成でほとんどのライブラリは扱えます。シリーズ名が先頭にある、言語が最後にある、言語フォルダが無い——そんな場合は**フォルダ検出の規則…**を開き、プレースホルダーでパスを記述してください。規則は順に試され、最初に一致したものが使われます。検出だけに影響し、ファイルの改名や移動は行いません。</p><p>構文、規則のフィールド、プレビューの手順は<a href="/KomaYomi-docs/ja/guide/folder-rules">フォルダ検出の規則</a>にまとめてあります。</p><h2 id="インポート、交換、復元" tabindex="-1">インポート、交換、復元 <a class="header-anchor" href="#インポート、交換、復元" aria-label="Permalink to &quot;インポート、交換、復元&quot;">​</a></h2><p>サイドバーには4つの入口があり、それぞれ役割が違います。</p><table tabindex="0"><thead><tr><th>入口</th><th>用途</th></tr></thead><tbody><tr><td><strong>マンガを追加</strong></td><td>既存の画像フォルダをライブラリにリンクします。</td></tr><tr><td><strong>プロジェクトファイル…</strong></td><td><code>.mnproj</code> パッケージ（画像 + 注釈 + テンプレート + 言語設定）をエクスポートまたはインポートします。</td></tr><tr><td><strong>交換ファイル…</strong></td><td><code>.mntpl</code> レイアウトテンプレート、<code>.mnexp</code> エクスポートテンプレート、単一の <code>.mnpage.json</code> ページをやり取りします。</td></tr><tr><td><strong>バックアップ / 復元</strong></td><td><code>data/</code> フォルダを ZIP にするか、以前の ZIP を復元します。</td></tr></tbody></table><p>インポートは最初に検証され、元のファイルは <code>data/backups/</code> にバックアップされます。ファイルの内容とバージョンの規則は <a href="/KomaYomi-docs/ja/guide/project-files">プロジェクトファイルと形式</a> を参照してください。</p><div class="tip custom-block"><p class="custom-block-title">インポートの順序</p><p>注釈を同じマシンに戻したいときは <strong>バックアップ</strong> を復元します。別のマシンへ移るときは <strong>プロジェクト</strong> をインポートします。レイアウト、エクスポートスタイル、1ページだけを共有したいときは <strong>交換ファイル</strong> を使います。</p></div><h2 id="ナビゲーションとパフォーマンス" tabindex="-1">ナビゲーションとパフォーマンス <a class="header-anchor" href="#ナビゲーションとパフォーマンス" aria-label="Permalink to &quot;ナビゲーションとパフォーマンス&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>ショートカット</th></tr></thead><tbody><tr><td>前 / 次のページ</td><td><code>[</code> / <code>]</code></td></tr><tr><td>コマ分割ワークベンチ</td><td><code>P</code></td></tr><tr><td>比較リーダー</td><td><code>C</code></td></tr><tr><td>サイドバーの表示切り替え</td><td><code>S</code></td></tr><tr><td>ノート欄の表示切り替え</td><td><code>N</code></td></tr><tr><td>エクスポートダイアログを開く</td><td><code>E</code></td></tr><tr><td>ヘルプ</td><td><code>?</code></td></tr></tbody></table><p>URL ハッシュはディープリンクに使えます：<code>#/&lt;volume&gt;/&lt;chapter&gt;/&lt;page&gt;/&lt;panels|compare&gt;</code>。</p><p>サムネイルはオンデマンドで生成され、<code>data/cache/thumbs/</code> にキャッシュされます。このフォルダは削除しても問題なく、次回表示時に再生成されます。画像形式はファイルヘッダーから判定されるため、実際は JPEG の <code>.png</code> も正しく表示されます。</p><h2 id="よくある落とし穴" tabindex="-1">よくある落とし穴 <a class="header-anchor" href="#よくある落とし穴" aria-label="Permalink to &quot;よくある落とし穴&quot;">​</a></h2><ul><li><strong>ファイル名を変えるとページ位置が変わります。</strong> 対応付けは並べ替えたインデックス順です。ページを挿入すると、それ以降のページがすべてずれます。新しいページは末尾に追加するか、話全体の名前を一貫して変更してください。<a href="/KomaYomi-docs/ja/guide/preprocess">画像の前処理と名前変更</a>を参照してください。</li><li><strong>言語が1つ欠けていてもエラーではありません。</strong> ページは開き、比較リーダーは欠けている言語のプレースホルダーを表示します。</li><li><strong>フォルダリンクはコピーではありません。</strong> 元のフォルダを移動または削除すると、ライブラリが壊れます。移動後はフォルダを追加し直してください。</li><li><strong>WebP は表示できますが、検出用にデコードされません。</strong> 自動分割に頼る場合は JPEG または PNG を使用してください（<a href="/KomaYomi-docs/ja/guide/panels">コマ分割ワークベンチ</a> 参照）。</li><li><strong>サイドバーが正解です。</strong> 巻や話が見つからない場合は、まずフォルダ名の大文字小文字と言語の別名を確認してください。</li><li><strong>言語ドロップダウンに目的のフォルダが出ない。</strong> 巻の設定で別の言語に割り当て済みです。</li></ul><h2 id="関連項目" tabindex="-1">関連項目 <a class="header-anchor" href="#関連項目" aria-label="Permalink to &quot;関連項目&quot;">​</a></h2><ul><li><a href="/KomaYomi-docs/ja/guide/preprocess">画像の前処理と名前変更</a> — 取り込み前にスキャンを整える。</li><li><a href="/KomaYomi-docs/ja/guide/folder-rules">フォルダ検出の規則</a> — 特殊なディレクトリ構成。</li><li><a href="/KomaYomi-docs/ja/guide/panels">コマ分割ワークベンチ</a> — ページを開いた後にすること。</li><li><a href="/KomaYomi-docs/ja/guide/project-files">プロジェクトファイルと形式</a> — <code>.mnproj</code> に含まれるもの。</li><li><a href="/KomaYomi-docs/ja/guide/remote">リモート保存とバックアップ</a> — 画像を NAS や WebDAV に置く方法。</li></ul>',50)])])}const E=d(r,[["render",i]]);export{k as __pageData,E as default};
